static inline int ai_has_word(const char* text, const char* word) {
    const char* p = strstr(text, word);
    while (p) {
        int start_ok = (p == text) || !isalnum((unsigned char)p[-1]);
        size_t len = strlen(word);
        int end_ok = (p[len] == '\0') || !isalnum((unsigned char)p[len]);
        if (start_ok && end_ok) return 1;
        p = strstr(p + 1, word);
    }
    return 0;
}

static inline int ai_has_sub(const char* text, const char* sub) {
    return strstr(text, sub) != NULL;
}

// Clues unlocked by asking specific intents (returns bit index 0..7, or -1 if none)
// Bit 0: Torn Ledger Receipt (intent 14)
// Bit 1: Spiced Cider Flask (intent 8, 18)
// Bit 2: Brass Guard Badge (intent 13, 15, 16, 17)
// Bit 3: Wheat Straw Stalk (intent 21, 22, 23)
// Bit 4: Broken Cane Tip (intent 24)
// Bit 5: Rope & Bandages (intent 19, 20)
// Bit 6: Tax Coin Sack (intent 5, 19)
// Bit 7: Stolen Gold Chest (intent 31, 32)
static inline int ai_intent_clue_bit(int intent_idx) {
    switch (intent_idx) {
        case 14: return 0; // Torn Ledger Receipt
        case 8:
        case 18: return 1; // Spiced Cider Flask
        case 13:
        case 15:
        case 16:
        case 17: return 2; // Brass Guard Badge / Key
        case 21:
        case 22:
        case 23: return 3; // Wheat Straw / Cart / Tools
        case 24: return 4; // Broken Cane Tip
        case 19:
        case 20: return 5; // Rope & Bandages / Sacks
        case 5:  return 6; // Tax Coin Sack
        case 31:
        case 32: return 7; // Stolen Gold Chest
        default: return -1;
    }
}

// Maps any natural-language player query to canonical intent index 0..33:
//  0: hi
//  1: how are you
//  2: who are you
//  3: what happened
//  4: how did they enter
//  5: what was in the vault
//  6: where were you
//  7: are you sure
//  8: did you fall asleep
//  9: did you stay inside after that
// 10: did you see anything
// 11: what did you see
// 12: who were the shadows
// 13: did they drop anything
// 14: what was on the paper
// 15: who has the key
// 16: is the duplicate key safe
// 17: where is the key
// 18: why were you dizzy (spiked drink)
// 19: who bought the sack
// 20: tell me about the buyer (rope/Wearing)
// 21: did you lose any tools
// 22: about that cart
// 23: did you see who was driving
// 24: whose cane
// 25: who do you suspect
// 26: who had a motive
// 27: who is the prime suspect
// 28: what do you think of the others
// 29: did you steal it
// 30: you are lying
// 31: confess
// 32: where is the loot
// 33: goodbye
static inline int ai_match_intent(const char* raw_query, int last_intent) {
    char q[160];
    size_t j = 0;
    for (size_t i = 0; raw_query[i] != '\0' && j < sizeof(q) - 1; i++) {
        char c = raw_query[i];
        if (isalnum((unsigned char)c) || c == ' ') {
            q[j++] = (char)tolower((unsigned char)c);
        } else if (c == '\'' || c == '-') {
            continue;
        } else {
            q[j++] = ' ';
        }
    }
    q[j] = '\0';

    // 33: Farewell
    if (ai_has_word(q, "bye") || ai_has_word(q, "goodbye") || ai_has_word(q, "farewell") ||
        ai_has_word(q, "thanks") || ai_has_sub(q, "thank you") || ai_has_sub(q, "see ya")) return 33;

    // 32: Where is the loot / hidden gold
    if (ai_has_sub(q, "where is the loot") || ai_has_sub(q, "where did you hide") ||
        ai_has_sub(q, "where is the gold") || ai_has_sub(q, "where did the wagon go") ||
        ai_has_sub(q, "hiding the loot") ||
        ((ai_has_word(q, "where") || ai_has_word(q, "hide") || ai_has_word(q, "hidden") || ai_has_word(q, "stash")) &&
         (ai_has_word(q, "loot") || ai_has_word(q, "gold") || ai_has_word(q, "treasure") || ai_has_word(q, "chest") || ai_has_word(q, "wagon")))) return 32;

    // 24: Cane tip
    if (ai_has_word(q, "cane") || ai_has_word(q, "bamboo") || ai_has_word(q, "ferrule") ||
        ai_has_sub(q, "walking stick") || ai_has_sub(q, "cracked tip")) return 24;

    // 18: Spiked drink / dizzy / drugged cider
    if (ai_has_word(q, "dizzy") || ai_has_word(q, "drink") || ai_has_word(q, "drank") ||
        ai_has_word(q, "cider") || ai_has_word(q, "flask") || ai_has_word(q, "spiked") ||
        ai_has_word(q, "drug") || ai_has_word(q, "drugged") || ai_has_word(q, "herb") ||
        ai_has_word(q, "herbs") || ai_has_word(q, "sedative") || ai_has_word(q, "poison")) return 18;

    // 20: Buyer details / rope / what was the buyer wearing
    if (ai_has_word(q, "buyer") || ai_has_word(q, "rope") || ai_has_word(q, "wearing") ||
        ai_has_word(q, "customer") || ai_has_word(q, "hooded") || ai_has_sub(q, "bought the rope")) return 20;

    // 19: Sacks / unusual supplies
    if (ai_has_word(q, "sack") || ai_has_word(q, "sacks") || ai_has_word(q, "canvas") ||
        ai_has_word(q, "burlap") || ai_has_word(q, "bag") || ai_has_word(q, "bags") ||
        ai_has_word(q, "supplies") || ai_has_sub(q, "who bought")) return 19;

    // 21: Tools / crowbar
    if (ai_has_word(q, "tool") || ai_has_word(q, "tools") || ai_has_word(q, "crowbar") ||
        ai_has_word(q, "prybar") || ai_has_word(q, "shovel") || ai_has_word(q, "hammer")) return 21;

    // 23: Who was driving the cart
    if ((ai_has_word(q, "driving") || ai_has_word(q, "driver") || ai_has_sub(q, "who took the cart") ||
         ai_has_sub(q, "who was driving"))) return 23;

    // 22: Cart / wagon / barn / tracks / straw
    if (ai_has_word(q, "cart") || ai_has_word(q, "wagon") || ai_has_word(q, "wheel") ||
        ai_has_word(q, "wheels") || ai_has_word(q, "tracks") || ai_has_word(q, "ruts") ||
        ai_has_word(q, "straw") || ai_has_word(q, "wheat") || ai_has_word(q, "barn")) return 22;

    // 14: Paper / receipt / ledger
    if (ai_has_word(q, "paper") || ai_has_word(q, "receipt") || ai_has_word(q, "note") ||
        ai_has_word(q, "slip") || ai_has_word(q, "ledger") || ai_has_word(q, "invoice") ||
        ai_has_word(q, "torn") || ai_has_word(q, "scrap")) return 14;

    // 15, 16, 17: Keys / desk / duplicate key
    if (ai_has_word(q, "key") || ai_has_word(q, "keys") || ai_has_word(q, "desk") ||
        ai_has_word(q, "drawer") || ai_has_word(q, "duplicate") || ai_has_sub(q, "guard house")) {
        if (ai_has_sub(q, "where is the key") || ai_has_sub(q, "where is the evidence") || ai_has_word(q, "hidden")) return 17;
        if (ai_has_word(q, "safe") || ai_has_word(q, "desk") || ai_has_word(q, "drawer") || ai_has_sub(q, "steal the key")) return 16;
        return 15;
    }

    // 13: Dropped anything / clues / evidence / footprints / badge
    if (ai_has_word(q, "drop") || ai_has_word(q, "dropped") || ai_has_word(q, "clues") ||
        ai_has_word(q, "clue") || ai_has_word(q, "evidence") || ai_has_word(q, "footprint") ||
        ai_has_word(q, "footprints") || ai_has_word(q, "badge") || ai_has_word(q, "crest")) return 13;

    // 4: How did they enter / lock / door
    if (ai_has_sub(q, "how did they") || ai_has_sub(q, "get in") || ai_has_sub(q, "break in") ||
        ai_has_sub(q, "pick the lock") || ai_has_word(q, "enter") || ai_has_word(q, "lock") ||
        ai_has_word(q, "door") || ai_has_word(q, "broken") || ai_has_word(q, "forced")) return 4;

    // 5: What was in the vault / what was stolen
    if (ai_has_sub(q, "what was in") || ai_has_sub(q, "what was stolen") || ai_has_sub(q, "how much") ||
        ai_has_word(q, "stolen") || ai_has_word(q, "taken") || ai_has_word(q, "deeds") ||
        ai_has_word(q, "treasury")) return 5;

    // 31: Confess / tell me the truth / what are you hiding
    if (ai_has_word(q, "confess") || ai_has_sub(q, "tell me the truth") || ai_has_sub(q, "what are you hiding") ||
        ai_has_sub(q, "who really organized") || ai_has_sub(q, "evidence proves") ||
        ai_has_word(q, "arrest") || ai_has_word(q, "surrender") || ai_has_word(q, "admit")) return 31;

    // 30: You are lying / debts / seen near vault
    if (ai_has_word(q, "lying") || ai_has_word(q, "liar") || ai_has_word(q, "lie") ||
        ai_has_word(q, "debts") || ai_has_word(q, "debt") || ai_has_sub(q, "you have a motive") ||
        ai_has_sub(q, "seen near")) return 30;

    // 29: Did you steal it / are you the thief / you stole it / guilty
    if (ai_has_sub(q, "did you steal") || ai_has_sub(q, "are you the thief") || ai_has_sub(q, "did you do it") ||
        ai_has_sub(q, "you stole") || ai_has_sub(q, "you are the thief") || ai_has_word(q, "guilty") ||
        ai_has_word(q, "culprit")) return 29;

    // 28: What do you think of the others / villagers
    if (ai_has_word(q, "others") || ai_has_word(q, "villagers") || ai_has_word(q, "everyone") ||
        ai_has_sub(q, "what about the") || ai_has_sub(q, "what do you think of")) return 28;

    // 27: Prime suspect / who really did it
    if (ai_has_sub(q, "prime suspect") || ai_has_sub(q, "who really did it") ||
        ai_has_sub(q, "who you think took")) return 27;

    // 26: Motive / acting suspicious
    if (ai_has_word(q, "motive") || ai_has_sub(q, "acting suspicious") || ai_has_sub(q, "tell me who you suspect")) return 26;

    // 25: Who do you suspect / who is the thief
    if (ai_has_word(q, "suspect") || ai_has_sub(q, "who did it") || ai_has_sub(q, "who is the thief") ||
        ai_has_sub(q, "any idea")) return 25;

    // 8: Asleep / sleeping
    if (ai_has_word(q, "asleep") || ai_has_word(q, "sleep") || ai_has_word(q, "sleeping") ||
        ai_has_word(q, "slept") || ai_has_word(q, "doze") || ai_has_word(q, "nap")) return 8;

    // 9: Midnight / stay inside / what did you do next / who saw you
    if (ai_has_word(q, "midnight") || ai_has_sub(q, "stay inside") || ai_has_sub(q, "what did you do next") ||
        ai_has_sub(q, "who saw you") || ai_has_sub(q, "after that")) return 9;

    // 7: Are you sure / were you alone / vouch / step outside
    if (ai_has_sub(q, "are you sure") || ai_has_sub(q, "were you alone") || ai_has_word(q, "vouch") ||
        ai_has_sub(q, "step outside") || ai_has_word(q, "prove") || ai_has_word(q, "verify")) return 7;

    // 6: Where were you / alibi
    if (ai_has_sub(q, "where were you") || ai_has_word(q, "alibi") || ai_has_sub(q, "what were you doing")) return 6;

    // 12: Shadows / whistling
    if (ai_has_word(q, "shadows") || ai_has_word(q, "shadow") || ai_has_word(q, "whistling") ||
        ai_has_word(q, "whistle") || ai_has_word(q, "figures")) return 12;

    // 11: What did you see / sounds / footsteps / lights
    if (ai_has_sub(q, "what did you see") || ai_has_sub(q, "what kind of sounds") ||
        ai_has_word(q, "footsteps") || ai_has_word(q, "lights") || ai_has_word(q, "sounds")) return 11;

    // 10: Did you see/hear/notice anything
    if (ai_has_word(q, "see") || ai_has_word(q, "hear") || ai_has_word(q, "notice") ||
        ai_has_word(q, "saw") || ai_has_word(q, "heard") || ai_has_word(q, "unusual")) return 10;

    // 2: Who are you / name / job
    if (ai_has_sub(q, "who are you") || ai_has_sub(q, "what do you do") || ai_has_sub(q, "your name") ||
        ai_has_sub(q, "what is your duty") || ai_has_sub(q, "what is your job")) return 2;

    // 1: How are you / business / patrol
    if (ai_has_sub(q, "how are you") || ai_has_sub(q, "how are things") || ai_has_sub(q, "how is business") ||
        ai_has_sub(q, "how goes")) return 1;

    // 3: What happened / robbery
    if (ai_has_word(q, "happened") || ai_has_word(q, "robbery") || ai_has_word(q, "theft") ||
        ai_has_word(q, "crime") || ai_has_word(q, "vault")) return 3;

    // 0: Hi / hello / greetings
    if (ai_has_word(q, "hi") || ai_has_word(q, "hello") || ai_has_word(q, "hey") ||
        ai_has_word(q, "greetings") || ai_has_sub(q, "good day") || ai_has_word(q, "halt")) return 0;

    // Contextual follow-up progression
    if (last_intent >= 0) {
        if (last_intent == 3) return 4;
        if (last_intent == 4) return 5;
        if (last_intent == 6) return 7;
        if (last_intent == 7) return 9;
        if (last_intent == 10) return 11;
        if (last_intent == 11) return 12;
        if (last_intent == 13) return 14;
        if (last_intent == 15) return 16;
        if (last_intent == 16) return 17;
        if (last_intent == 19) return 20;
        if (last_intent == 22) return 23;
        if (last_intent == 25) return 26;
        if (last_intent == 26) return 27;
        if (last_intent == 29) return 30;
        if (last_intent == 30) return 31;
        if (last_intent == 31) return 32;
    }

    return 3;
}

